var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();string log="";
 foreach(var pair in new[]{new UnityEngine.Vector2(42,74),new UnityEngine.Vector2(10,42),new UnityEngine.Vector2(18,48)}){
  float max=0;string worst="";
  foreach(float reach in new[]{.75f,1.975f})for(int i=0;i<360;i++){
   var q=UnityEngine.Quaternion.Euler(0,0,i);rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(reach,.074f,0);rig.Pose();
   var l=Character.Control.PaddleCharacterVisual.PixelPosition(rig.paddle,new UnityEngine.Vector2(24,pair.x));var r=Character.Control.PaddleCharacterVisual.PixelPosition(rig.paddle,new UnityEngine.Vector2(24,pair.y));
   var sl=rig.body.position+rig.body.up*.66f-rig.body.right*.245f;var sr=rig.body.position+rig.body.up*.66f+rig.body.right*.245f;
   float d=UnityEngine.Mathf.Max(UnityEngine.Vector3.Distance(sl,l),UnityEngine.Vector3.Distance(sr,r));if(d>max){max=d;worst="rotation="+i+" radial="+reach;}
  }
  log+="source grip rows "+pair+": max shoulder-wrist distance="+max+", natural arm=.98, "+worst+"\n";
 }
 System.IO.File.WriteAllText("scripts/player-locked-grips-20261111/tail-comparison.txt",log);UnityEngine.Debug.Log(log);
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
